package vn.alarm.pro;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.provider.Settings;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity {
 LinearLayout root,body; int tab=0,bg=0xff101b30,gold=0xffffd780; Handler handler=new Handler(); CountDownTimer timer; long start=0,elapsed=0; TextView watch; boolean running=false;
 int dp(int x){return (int)(x*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);show();}
 public void onResume(){super.onResume();JSONArray a=Store.all(this);for(int i=0;i<a.length();i++)Store.schedule(this,a.optJSONObject(i),0);}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));d.setStroke(dp(1),0xff756344);return d;}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(gold);t.setPadding(dp(8),dp(8),dp(8),dp(8));return t;}
 Button button(String s,View.OnClickListener f){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(gold);b.setBackground(shape(0xff23334d));b.setOnClickListener(f);return b;}
 void add(LinearLayout l,View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));l.addView(v,p);}
 LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 void show(){int theme=getPreferences(0).getInt("theme",0);bg=new int[]{0xff101b30,0xff41283d,0xff103b39,0xff10102a}[theme];root=vertical();root.setBackgroundColor(bg);root.setPadding(dp(12),dp(10),dp(12),dp(8));setContentView(root);TextView title=text("Báo Thức Thông Minh\nPro Max",24);title.setGravity(17);title.setTypeface(null,Typeface.BOLD);add(root,title);ScrollView sc=new ScrollView(this);body=vertical();sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout nav=new LinearLayout(this);String[] names={"Báo thức","Hẹn giờ","Bấm giờ","Ghi chú","Cài đặt"};for(int i=0;i<5;i++){final int n=i;Button b=button(names[i],v->{tab=n;show();});b.setTextSize(10);b.setPadding(0,0,0,0);nav.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));}root.addView(nav);if(tab==0)alarms();if(tab==1)countdown();if(tab==2)stopwatch();if(tab==3)notes();if(tab==4)settings();}
 void alarms(){ImageView im=new ImageView(this);im.setImageResource(R.drawable.icon);im.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(im,new LinearLayout.LayoutParams(-1,dp(120)));TextView clock=text(new java.text.SimpleDateFormat("HH:mm",Locale.US).format(new Date()),48);clock.setGravity(17);add(body,clock);TextView date=text(new java.text.SimpleDateFormat("EEEE, dd/MM/yyyy",new Locale("vi","VN")).format(new Date()),16);date.setGravity(17);add(body,date);add(body,button("＋ Thêm báo thức",v->edit(null)));JSONArray a=Store.all(this);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);LinearLayout card=vertical();card.setPadding(dp(10),dp(8),dp(10),dp(8));card.setBackground(shape(0xff23334d));LinearLayout row=new LinearLayout(this);TextView t=text(String.format(Locale.US,"%02d:%02d",o.optInt("h"),o.optInt("m")),32);row.addView(t,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setChecked(o.optBoolean("on"));row.addView(sw);sw.setOnCheckedChangeListener((b,on)->{Store.put(o,"on",on);Store.update(this,o);Store.schedule(this,o,0);permission();});card.addView(row);add(card,text(o.optString("note")+"\n"+(o.optInt("days")==127?"Hằng ngày":o.optInt("days")==0?"Một lần":"Theo ngày đã chọn"),16));add(card,button("Chỉnh sửa",v->edit(o)));add(body,card);}}
 void permission(){AlarmManager a=getSystemService(AlarmManager.class);if(Build.VERSION.SDK_INT>=31&&!a.canScheduleExactAlarms())new AlertDialog.Builder(this).setMessage("Cần cho phép báo thức chính xác để chuông reo đúng giờ.").setPositiveButton("Cấp quyền",(d,w)->startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())))).setNegativeButton("Để sau",null).show();}
 void edit(JSONObject old){JSONObject o=old==null?new JSONObject():old;LinearLayout l=vertical();l.setPadding(dp(16),0,dp(16),0);TimePicker time=new TimePicker(this);time.setIs24HourView(true);time.setHour(o.optInt("h",6));time.setMinute(o.optInt("m",0));add(l,time);EditText note=new EditText(this);note.setHint("Nội dung ghi chú cần đọc");note.setText(o.optString("note"));add(l,note);add(l,text("Lặp lại (không chọn = một lần)",16));String[] days={"CN","T2","T3","T4","T5","T6","T7"};CheckBox[] checks=new CheckBox[7];LinearLayout r=new LinearLayout(this);for(int i=0;i<7;i++){checks[i]=new CheckBox(this);checks[i].setText(days[i]);checks[i].setTextSize(10);checks[i].setPadding(0,0,0,0);checks[i].setChecked((o.optInt("days",127)&(1<<i))!=0);r.addView(checks[i],new LinearLayout.LayoutParams(0,-2,1));}add(l,r);add(l,text("Âm lượng báo thức (%)",16));SeekBar volume=new SeekBar(this);volume.setMax(100);volume.setProgress(o.optInt("volume",100));add(l,volume);Switch vibrate=new Switch(this);vibrate.setText("Rung khi báo thức");vibrate.setChecked(o.optBoolean("vibrate",true));add(l,vibrate);ScrollView scroll=new ScrollView(this);scroll.addView(l);AlertDialog.Builder d=new AlertDialog.Builder(this).setTitle("Thiết lập báo thức").setView(scroll).setNegativeButton("Hủy",null).setPositiveButton("Lưu",(x,y)->{if(old==null)Store.put(o,"id",(int)(System.currentTimeMillis()&0x7fffffff));Store.put(o,"h",time.getHour());Store.put(o,"m",time.getMinute());Store.put(o,"note",note.getText().toString());int mask=0;for(int i=0;i<7;i++)if(checks[i].isChecked())mask|=1<<i;Store.put(o,"days",mask);Store.put(o,"volume",volume.getProgress());Store.put(o,"vibrate",vibrate.isChecked());Store.put(o,"on",true);Store.update(this,o);Store.schedule(this,o,0);show();permission();});if(old!=null)d.setNeutralButton("Xóa",(x,y)->{Store.put(o,"on",false);Store.schedule(this,o,0);JSONArray a=Store.all(this),b=new JSONArray();for(int i=0;i<a.length();i++)if(a.optJSONObject(i).optInt("id")!=o.optInt("id"))b.put(a.optJSONObject(i));Store.save(this,b);show();});d.show();}
 void countdown(){EditText mins=new EditText(this);mins.setInputType(2);mins.setHint("Số phút");mins.setText("15");add(body,mins);TextView t=text("00:15:00",42);t.setGravity(17);add(body,t);add(body,button("Bắt đầu",v->{try{long ms=Long.parseLong(mins.getText().toString())*60000;if(ms<=0)return;if(timer!=null)timer.cancel();timer=new CountDownTimer(ms,1000){public void onTick(long m){t.setText(fmt(m));}public void onFinish(){t.setText("Hết giờ!");new AlertDialog.Builder(MainActivity.this).setMessage("Đã hết thời gian hẹn giờ!").setPositiveButton("Đóng",null).show();android.media.RingtoneManager.getRingtone(MainActivity.this,android.media.RingtoneManager.getDefaultUri(2)).play();}}.start();}catch(Exception e){}}));add(body,button("Hủy hẹn giờ",v->{if(timer!=null)timer.cancel();t.setText("00:00:00");}));}
 String fmt(long ms){long s=ms/1000;return String.format(Locale.US,"%02d:%02d:%02d",s/3600,s/60%60,s%60);}
 Runnable tick=new Runnable(){public void run(){if(running){if(watch!=null)watch.setText(fmt(elapsed+SystemClock.elapsedRealtime()-start));handler.postDelayed(this,200);}}};
 void stopwatch(){watch=text(fmt(elapsed+(running?SystemClock.elapsedRealtime()-start:0)),42);watch.setGravity(17);add(body,watch);add(body,button("Bắt đầu / Tiếp tục",v->{if(!running){running=true;start=SystemClock.elapsedRealtime();handler.post(tick);}}));add(body,button("Tạm dừng",v->{if(running){elapsed+=SystemClock.elapsedRealtime()-start;running=false;}}));add(body,button("Đặt lại",v->{running=false;elapsed=0;watch.setText(fmt(0));}));}
 void notes(){EditText e=new EditText(this);e.setHint("Ghi chú công việc hằng ngày");e.setMinLines(8);e.setText(getPreferences(0).getString("notes",""));add(body,e);add(body,button("Lưu ghi chú",v->{getPreferences(0).edit().putString("notes",e.getText().toString()).apply();Toast.makeText(this,"Đã lưu",0).show();}));}
 void settings(){String[] themes={"Hoàng Kim","Bình Minh","Xanh Ngọc","Đêm Huyền Bí"};add(body,text("Giao diện",22));for(int i=0;i<4;i++){final int n=i;add(body,button(themes[i],v->{getPreferences(0).edit().putInt("theme",n).apply();show();}));}add(body,button("Quyền báo thức chính xác",v->permission()));add(body,button("Cài đặt giọng đọc tiếng Việt",v->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){Toast.makeText(this,"Mở cài đặt chuyển văn bản thành giọng nói của Android",1).show();}}));if(Build.VERSION.SDK_INT>=34)add(body,button("Quyền hiển thị khi khóa màn hình",v->startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName())))));add(body,text("Phiên bản 1.0 • Không quảng cáo",16));}
}